package com.uangku.app;

/**
 * Renders the complete UangKu Android application layout and view hierarchy.
 */
public final class LedgerView {
    private LedgerView() {}

    public static String buildDocument() {
        StringBuilder doc = new StringBuilder(96000);
        doc.append("<!DOCTYPE html>\n<html lang=\"id\" data-theme=\"dark\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no, viewport-fit=cover\" />\n  <meta name=\"theme-color\" content=\"#0B0C0E\" id=\"meta-theme-color\" />\n  <meta name=\"description\" content=\"UangKu \u2014 Aplikasi Android pencatat keuangan pribadi sederhana, tampilan premium, dengan grafik harian, mingguan, bulanan dan 100% offline.\" />\n  \n  <title>UangKu \u2014 Catatan Keuangan</title>\n  ");
        doc.append("<style>\n");
        doc.append(LedgerStyles.get());
        doc.append("\n</style>");
        doc.append("\n</head>\n<body>\n  <!-- Splash Screen / Opening Transition Editorial -->\n  <div id=\"splash-screen\" class=\"splash-screen\">\n    <div class=\"splash-content\">\n      <div class=\"splash-logo-wrapper\">\n        <svg viewBox=\"0 0 512 512\" width=\"100%\" height=\"100%\" class=\"splash-svg-logo\" aria-label=\"Logo UangKu\">\n          <defs>\n            <linearGradient id=\"splashBg\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n              <stop offset=\"0%\" stop-color=\"#16181D\" />\n              <stop offset=\"100%\" stop-color=\"#0B0C0E\" />\n            </linearGradient>\n            <linearGradient id=\"splashEmerald\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n              <stop offset=\"0%\" stop-color=\"#00E599\" />\n              <stop offset=\"100%\" stop-color=\"#00B377\" />\n            </linearGradient>\n            <linearGradient id=\"splashGold\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n              <stop offset=\"0%\" stop-color=\"#FDE68A\" />\n              <stop offset=\"100%\" stop-color=\"#D97706\" />\n            </linearGradient>\n          </defs>\n          <rect width=\"512\" height=\"512\" rx=\"115\" fill=\"url(#splashBg)\" />\n          <circle cx=\"256\" cy=\"256\" r=\"195\" fill=\"none\" stroke=\"url(#splashEmerald)\" stroke-width=\"4\" opacity=\"0.22\" />\n          <!-- Kartu Emas Atas -->\n          <path d=\"M146 124 H346 A26 26 0 0 1 372 150 V168 H120 V150 A26 26 0 0 1 146 124 Z\" fill=\"url(#splashGold)\" />\n          <!-- Badan Dompet Hijau Zamrud -->\n          <rect x=\"110\" y=\"152\" width=\"292\" height=\"208\" rx=\"40\" fill=\"url(#splashEmerald)\" />\n          <!-- Garis Grafik Naik Putih -->\n          <polyline points=\"154,298 206,246 246,272 302,202\" fill=\"none\" stroke=\"#0B0C0E\" stroke-width=\"18\" stroke-linecap=\"round\" stroke-linejoin=\"round\" />\n          <circle cx=\"302\" cy=\"202\" r=\"12\" fill=\"#0B0C0E\" />\n          <!-- Kancing Dompet Kanan -->\n          <rect x=\"318\" y=\"226\" width=\"96\" height=\"60\" rx=\"18\" fill=\"#16181D\" />\n          <circle cx=\"348\" cy=\"256\" r=\"13\" fill=\"url(#splashGold)\" />\n        </svg>\n      </div>\n      <h1 class=\"splash-title\">UangKu</h1>\n      <p class=\"splash-subtitle\">FINANCIAL PRECISION &amp; LEDGER</p>\n      <div class=\"splash-spinner\">\n        <span class=\"spinner-dot\"></span>\n      </div>\n      <p class=\"splash-credit\">Created by <strong>MasPur</strong></p>\n    </div>\n  </div>\n\n  <div class=\"app-shell\">\n    <!-- Top App Bar -->\n    <header class=\"app-header\">\n      <div class=\"brand\">\n        <div class=\"brand-logo\" aria-hidden=\"true\">\n          <svg viewBox=\"0 0 512 512\" width=\"100%\" height=\"100%\" class=\"header-svg-logo\" aria-hidden=\"true\">\n            <defs>\n              <linearGradient id=\"hdrBg\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n                <stop offset=\"0%\" stop-color=\"#16181D\" />\n                <stop offset=\"100%\" stop-color=\"#0B0C0E\" />\n              </linearGradient>\n              <linearGradient id=\"hdrEmerald\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n                <stop offset=\"0%\" stop-color=\"#00E599\" />\n                <stop offset=\"100%\" stop-color=\"#00B377\" />\n              </linearGradient>\n              <linearGradient id=\"hdrGold\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n                <stop offset=\"0%\" stop-color=\"#FDE68A\" />\n                <stop offset=\"100%\" stop-color=\"#D97706\" />\n              </linearGradient>\n            </defs>\n            <rect width=\"512\" height=\"512\" rx=\"115\" fill=\"url(#hdrBg)\" />\n            <circle cx=\"256\" cy=\"256\" r=\"195\" fill=\"none\" stroke=\"url(#hdrEmerald)\" stroke-width=\"5\" opacity=\"0.25\" />\n            <!-- Kartu Emas Atas -->\n            <path d=\"M146 124 H346 A26 26 0 0 1 372 150 V168 H120 V150 A26 26 0 0 1 146 124 Z\" fill=\"url(#hdrGold)\" />\n            <!-- Badan Dompet Hijau Zamrud -->\n            <rect x=\"110\" y=\"152\" width=\"292\" height=\"208\" rx=\"40\" fill=\"url(#hdrEmerald)\" />\n            <!-- Garis Grafik Naik -->\n            <polyline points=\"154,298 206,246 246,272 302,202\" fill=\"none\" stroke=\"#0B0C0E\" stroke-width=\"20\" stroke-linecap=\"round\" stroke-linejoin=\"round\" />\n            <circle cx=\"302\" cy=\"202\" r=\"14\" fill=\"#0B0C0E\" />\n            <!-- Kancing Dompet Kanan -->\n            <rect x=\"318\" y=\"226\" width=\"96\" height=\"60\" rx=\"18\" fill=\"#16181D\" />\n            <circle cx=\"348\" cy=\"256\" r=\"14\" fill=\"url(#hdrGold)\" />\n          </svg>\n        </div>\n        <div class=\"brand-text\">\n          <h1>UangKu</h1>\n          <span class=\"status-badge\" id=\"offline-badge\">\n            <span class=\"status-dot\"></span>\n            <span id=\"status-text\">Mode Offline</span>\n          </span>\n        </div>\n      </div>\n\n      <div class=\"header-actions\">\n        <!-- Toggle Light / Dark Mode -->\n        <button type=\"button\" id=\"btn-theme-toggle\" class=\"icon-btn\" title=\"Ganti Tema Terang / Gelap\" aria-label=\"Ganti Tema\">\n          <!-- Sun icon (shown in dark mode) -->\n          <svg class=\"icon-sun\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n            <circle cx=\"12\" cy=\"12\" r=\"5\" />\n            <line x1=\"12\" y1=\"1\" x2=\"12\" y2=\"3\" />\n            <line x1=\"12\" y1=\"21\" x2=\"12\" y2=\"23\" />\n            <line x1=\"4.22\" y1=\"4.22\" x2=\"5.64\" y2=\"5.64\" />\n            <line x1=\"18.36\" y1=\"18.36\" x2=\"19.78\" y2=\"19.78\" />\n            <line x1=\"1\" y1=\"12\" x2=\"3\" y2=\"12\" />\n            <line x1=\"21\" y1=\"12\" x2=\"23\" y2=\"12\" />\n            <line x1=\"4.22\" y1=\"19.78\" x2=\"5.64\" y2=\"18.36\" />\n            <line x1=\"18.36\" y1=\"5.64\" x2=\"19.78\" y2=\"4.22\" />\n          </svg>\n          <!-- Moon icon (shown in light mode) -->\n          <svg class=\"icon-moon\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n            <path d=\"M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z\" />\n          </svg>\n        </button>\n      </div>\n    </header>\n\n    <!-- Main Scrollable Content -->\n    <main class=\"app-content\">\n      <!-- Hero Balance Card -->\n      <section class=\"balance-card\" aria-label=\"Ringkasan Saldo\">\n        <div class=\"balance-top\">\n          <div>\n            <p class=\"balance-label\">Total Saldo Saat Ini</p>\n            <div class=\"balance-amount-row\">\n              <h2 id=\"total-balance\" class=\"balance-amount\">Rp 0</h2>\n              <button type=\"button\" id=\"btn-toggle-visibility\" class=\"eye-btn\" aria-label=\"Sembunyikan atau tampilkan nominal\">\n                <svg id=\"eye-open\" width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n                  <path d=\"M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z\" />\n                  <circle cx=\"12\" cy=\"12\" r=\"3\" />\n                </svg>\n                <svg id=\"eye-closed\" class=\"hidden\" width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n                  <path d=\"M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19m-6.72-1.07a3 3 0 1 1-4.24-4.24\" />\n                  <line x1=\"1\" y1=\"1\" x2=\"23\" y2=\"23\" />\n                </svg>\n              </button>\n            </div>\n          </div>\n          <span class=\"card-chip\" aria-hidden=\"true\">\n            <svg width=\"26\" height=\"20\" viewBox=\"0 0 26 20\" fill=\"none\">\n              <rect x=\"0.5\" y=\"0.5\" width=\"25\" height=\"19\" rx=\"3.5\" stroke=\"currentColor\" stroke-opacity=\"0.35\"/>\n              <path d=\"M8 1V19M18 1V19M1 7H8M18 7H25M1 13H8M18 13H25\" stroke=\"currentColor\" stroke-opacity=\"0.35\"/>\n            </svg>\n          </span>\n        </div>\n\n        <div class=\"balance-stats\">\n          <div class=\"stat-box income\">\n            <div class=\"stat-icon\">\n              <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n                <line x1=\"12\" y1=\"19\" x2=\"12\" y2=\"5\" />\n                <polyline points=\"5 12 12 5 19 12\" />\n              </svg>\n            </div>\n            <div class=\"stat-info\">\n              <span>Pemasukan</span>\n              <strong id=\"period-income\">Rp 0</strong>\n            </div>\n          </div>\n\n          <div class=\"stat-divider\"></div>\n\n          <div class=\"stat-box expense\">\n            <div class=\"stat-icon\">\n              <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n                <line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\" />\n                <polyline points=\"19 12 12 19 5 12\" />\n              </svg>\n            </div>\n            <div class=\"stat-info\">\n              <span>Pengeluaran</span>\n              <strong id=\"period-expense\">Rp 0</strong>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- Financial Analytics Chart Section (Harian, Mingguan, Bulanan) -->\n      <section class=\"card-surface chart-section\" aria-label=\"Grafik Keuangan\">\n        <div class=\"section-header\">\n          <div>\n            <h3 class=\"section-title\">Analisis Grafik</h3>\n            <p class=\"section-subtitle\" id=\"chart-range-label\">7 Hari Terakhir</p>\n          </div>\n\n          <!-- Period Segmented Control -->\n          <div class=\"segmented-control\" role=\"tablist\" aria-label=\"Periode Grafik\">\n            <button type=\"button\" role=\"tab\" aria-selected=\"true\" class=\"segment-btn active\" data-period=\"daily\">Harian</button>\n            <button type=\"button\" role=\"tab\" aria-selected=\"false\" class=\"segment-btn\" data-period=\"weekly\">Mingguan</button>\n            <button type=\"button\" role=\"tab\" aria-selected=\"false\" class=\"segment-btn\" data-period=\"monthly\">Bulanan</button>\n          </div>\n        </div>\n\n        <!-- Navigation Slider / Stepper (Bisa geser ke hari/periode sebelumnya) -->\n        <div class=\"chart-navigator\" id=\"chart-navigator\">\n          <button type=\"button\" id=\"btn-chart-prev\" class=\"nav-arrow-btn\" aria-label=\"Lihat periode sebelumnya\" title=\"Geser ke hari/periode sebelumnya\">\n            <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n              <polyline points=\"15 18 9 12 15 6\" />\n            </svg>\n            <span class=\"nav-btn-text\">Sebelumnya</span>\n          </button>\n\n          <span class=\"nav-current-window\" id=\"chart-window-label\">Rentang Terkini</span>\n\n          <div class=\"nav-right-controls\">\n            <button type=\"button\" id=\"btn-chart-reset\" class=\"nav-reset-btn hidden\" title=\"Kembali ke Hari Ini\">\n              Hari Ini\n            </button>\n            <button type=\"button\" id=\"btn-chart-next\" class=\"nav-arrow-btn\" aria-label=\"Lihat periode berikutnya\" title=\"Geser ke hari/periode berikutnya\" disabled>\n              <span class=\"nav-btn-text\">Berikutnya</span>\n              <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n                <polyline points=\"9 18 15 12 9 6\" />\n              </svg>\n            </button>\n          </div>\n        </div>\n\n        <!-- Legend & Net Flow -->\n        <div class=\"chart-meta\">\n          <div class=\"chart-legend\">\n            <span class=\"legend-item\">\n              <span class=\"legend-dot income-dot\"></span> Pemasukan\n            </span>\n            <span class=\"legend-item\">\n              <span class=\"legend-dot expense-dot\"></span> Pengeluaran\n            </span>\n          </div>\n          <div class=\"chart-net\" id=\"chart-net-summary\">\n            Selisih: <strong>Rp 0</strong>\n          </div>\n        </div>\n\n        <!-- Interactive SVG Bar & Trend Chart -->\n        <div class=\"chart-container\" id=\"chart-container\">\n          <!-- Rendered dynamically by app.js -->\n        </div>\n\n        <!-- Selected Bar Detail Pill -->\n        <div class=\"chart-tooltip-bar\" id=\"chart-detail-bar\">\n          <span class=\"detail-period\" id=\"detail-period-name\">Pilih batang grafik untuk detail</span>\n          <div class=\"detail-values\">\n            <span class=\"detail-in\" id=\"detail-in\">+Rp 0</span>\n            <span class=\"detail-out\" id=\"detail-out\">-Rp 0</span>\n          </div>\n        </div>\n      </section>\n\n      <!-- Recent Transactions List -->\n      <section class=\"transactions-section\" aria-label=\"Riwayat Catatan\">\n        <div class=\"section-header tx-header\">\n          <div>\n            <h3 class=\"section-title\">Catatan Transaksi</h3>\n            <p class=\"section-subtitle\" id=\"tx-count-label\">Semua catatan tersimpan di perangkat</p>\n          </div>\n\n          <!-- Simple Filter Pills -->\n          <div class=\"filter-pills\">\n            <button type=\"button\" class=\"pill-btn active\" data-filter=\"all\">Semua</button>\n            <button type=\"button\" class=\"pill-btn\" data-filter=\"income\">Masuk</button>\n            <button type=\"button\" class=\"pill-btn\" data-filter=\"expense\">Keluar</button>\n          </div>\n        </div>\n\n        <!-- Fitur Search Transaksi -->\n        <div class=\"search-box-wrapper\">\n          <svg class=\"search-icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n            <circle cx=\"11\" cy=\"11\" r=\"8\" />\n            <line x1=\"21\" y1=\"21\" x2=\"16.65\" y2=\"16.65\" />\n          </svg>\n          <input\n            type=\"search\"\n            id=\"tx-search-input\"\n            class=\"search-input\"\n            placeholder=\"Cari transaksi (contoh: makan, kopi, gaji)...\"\n            autocomplete=\"off\"\n          />\n          <button type=\"button\" id=\"btn-clear-search\" class=\"clear-search-btn hidden\" aria-label=\"Hapus pencarian\">\n            <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n              <line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\" />\n              <line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\" />\n            </svg>\n          </button>\n        </div>\n\n        <div id=\"transactions-list\" class=\"transactions-list\">\n          <!-- Rendered dynamically by app.js -->\n        </div>\n\n        <!-- Pagination Controls (Next Page / Prev Page) -->\n        <div class=\"pagination-container\" id=\"pagination-container\">\n          <button type=\"button\" id=\"btn-prev-page\" class=\"page-nav-btn\" disabled aria-label=\"Halaman Sebelumnya\">\n            <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n              <polyline points=\"15 18 9 12 15 6\" />\n            </svg>\n            <span>Sebelumnya</span>\n          </button>\n          <span class=\"page-indicator\" id=\"page-indicator\">Hal 1 dari 1</span>\n          <button type=\"button\" id=\"btn-next-page\" class=\"page-nav-btn\" disabled aria-label=\"Halaman Selanjutnya\">\n            <span>Next Page</span>\n            <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n              <polyline points=\"9 18 15 12 9 6\" />\n            </svg>\n          </button>\n        </div>\n      </section>\n    </main>\n\n    <!-- Bottom Action Bar with Floating Add Button -->\n    <div class=\"bottom-bar\">\n      <button type=\"button\" id=\"btn-add-tx\" class=\"fab-primary\" aria-label=\"Catat Transaksi Baru\">\n        <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n          <line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\" />\n          <line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\" />\n        </svg>\n        <span>Catat Keuangan</span>\n      </button>\n    </div>\n  </div>\n\n  <!-- Modal Bottom Sheet: Tambah / Edit Catatan -->\n  <div id=\"tx-modal\" class=\"modal-overlay hidden\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"modal-title\">\n    <div class=\"modal-sheet\">\n      <div class=\"sheet-handle\"></div>\n      <div class=\"modal-header\">\n        <h3 id=\"modal-title\">Catat Keuangan</h3>\n        <button type=\"button\" id=\"btn-close-modal\" class=\"icon-btn close-btn\" aria-label=\"Tutup\">\n          <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n            <line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\" />\n            <line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\" />\n          </svg>\n        </button>\n      </div>\n\n      <form id=\"tx-form\" autocomplete=\"off\">\n        <input type=\"hidden\" id=\"tx-id\" value=\"\" />\n\n        <!-- Type Switcher (Pengeluaran / Pemasukan) -->\n        <div class=\"type-switcher\">\n          <button type=\"button\" class=\"type-btn active expense-mode\" data-type=\"expense\" id=\"type-expense\">\n            <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n              <line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\" />\n              <polyline points=\"19 12 12 19 5 12\" />\n            </svg>\n            Pengeluaran\n          </button>\n          <button type=\"button\" class=\"type-btn income-mode\" data-type=\"income\" id=\"type-income\">\n            <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n              <line x1=\"12\" y1=\"19\" x2=\"12\" y2=\"5\" />\n              <polyline points=\"5 12 12 5 19 12\" />\n            </svg>\n            Pemasukan\n          </button>\n        </div>\n\n        <!-- Nominal Input -->\n        <div class=\"form-group amount-input-group\">\n          <label for=\"tx-amount\">Nominal (Rp)</label>\n          <div class=\"amount-field-wrapper\">\n            <span class=\"currency-prefix\">Rp</span>\n            <input\n              type=\"text\"\n              inputmode=\"numeric\"\n              id=\"tx-amount\"\n              placeholder=\"0\"\n              required\n              aria-required=\"true\"\n            />\n          </div>\n          <!-- Quick Nominal Chips -->\n          <div class=\"quick-amounts\">\n            <button type=\"button\" class=\"chip-amount\" data-val=\"10000\">+10 Rb</button>\n            <button type=\"button\" class=\"chip-amount\" data-val=\"25000\">+25 Rb</button>\n            <button type=\"button\" class=\"chip-amount\" data-val=\"50000\">+50 Rb</button>\n            <button type=\"button\" class=\"chip-amount\" data-val=\"100000\">+100 Rb</button>\n          </div>\n        </div>\n\n        <!-- Category Grid -->\n        <div class=\"form-group\">\n          <label>Kategori</label>\n          <div class=\"category-grid\" id=\"category-grid\">\n            <!-- Populated by JS based on income/expense -->\n          </div>\n        </div>\n\n        <!-- Note Row -->\n        <div class=\"form-group\">\n          <label for=\"tx-note\">Catatan (Opsional)</label>\n          <input type=\"text\" id=\"tx-note\" placeholder=\"Contoh: Makan siang\" maxlength=\"60\" />\n        </div>\n\n        <!-- Date & Time Row -->\n        <div class=\"form-row\">\n          <div class=\"form-group flex-1\">\n            <label for=\"tx-date\">Tanggal</label>\n            <input type=\"date\" id=\"tx-date\" required />\n          </div>\n          <div class=\"form-group time-group\">\n            <label for=\"tx-time\">Jam</label>\n            <input type=\"time\" id=\"tx-time\" required />\n          </div>\n        </div>\n\n        <div class=\"modal-actions\">\n          <button type=\"button\" id=\"btn-delete-tx\" class=\"btn-danger hidden\">\n            <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n              <polyline points=\"3 6 5 6 21 6\"></polyline>\n              <path d=\"M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2\"></path>\n              <line x1=\"10\" y1=\"11\" x2=\"10\" y2=\"17\"></line>\n              <line x1=\"14\" y1=\"11\" x2=\"14\" y2=\"17\"></line>\n            </svg>\n            Hapus Catatan\n          </button>\n          <button type=\"submit\" class=\"btn-submit\" id=\"btn-save-tx\">Simpan Catatan</button>\n        </div>\n      </form>\n    </div>\n  </div>\n\n  <!-- Dialog Konfirmasi Hapus Transaksi -->\n  <div id=\"delete-confirm-modal\" class=\"modal-overlay hidden\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"confirm-title\">\n    <div class=\"modal-sheet confirm-sheet\">\n      <div class=\"confirm-icon-box\">\n        <svg width=\"28\" height=\"28\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n          <polyline points=\"3 6 5 6 21 6\"></polyline>\n          <path d=\"M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2\"></path>\n          <line x1=\"10\" y1=\"11\" x2=\"10\" y2=\"17\"></line>\n          <line x1=\"14\" y1=\"11\" x2=\"14\" y2=\"17\"></line>\n        </svg>\n      </div>\n      <h3 id=\"confirm-title\" class=\"confirm-title\">Hapus Catatan Ini?</h3>\n      <p class=\"confirm-desc\" id=\"confirm-tx-info\">Catatan transaksi yang dipilih akan dihapus secara permanen dari perangkat Anda.</p>\n      <div class=\"confirm-actions\">\n        <button type=\"button\" id=\"btn-cancel-delete\" class=\"btn-cancel\">Batal</button>\n        <button type=\"button\" id=\"btn-confirm-delete\" class=\"btn-confirm-danger\">Ya, Hapus</button>\n      </div>\n    </div>\n  </div>\n\n  ");
        doc.append("<script>\n");
        doc.append(LedgerEngine.get());
        doc.append("\n</script>");
        doc.append("\n</body>\n</html>\n");
        return doc.toString();
    }
}
